        E("global_vs_local_text_prefix", "전역 접두사와 지역 접두사", "def format_with_global_and_local_prefix(text: str, local_prefix: str) -> tuple[str, str]:", "GLOBAL_TEXT_PREFIX와 지역 매개변수 local_prefix를 각각 text 앞에 붙여 (전역 접두사 결과, 지역 접두사 결과)를 반환한다.", "모듈 전역 문자열과 호출별 지역 문자열을 나란히 사용", "format_with_global_and_local_prefix('data', 'LOCAL:') == ('GLOBAL:data', 'LOCAL:data')", "format_with_global_and_local_prefix('', '#') == ('GLOBAL:', '#')", "format_with_global_and_local_prefix('x', '') == ('GLOBAL:x', 'x')", prelude="GLOBAL_TEXT_PREFIX = 'GLOBAL:'"),
        E("global_vs_local_score_bonus", "전역 보너스와 지역 보너스", "def score_with_global_and_local_bonus(score: int, local_bonus: int) -> tuple[int, int]:", "score에 GLOBAL_SCORE_BONUS와 local_bonus를 각각 더해 (전역 보너스 점수, 지역 보너스 점수)를 반환한다.", "공통 전역 설정과 호출별 지역 설정 비교", "score_with_global_and_local_bonus(80, 5) == (90, 85)", "score_with_global_and_local_bonus(0, 0) == (10, 0)", "score_with_global_and_local_bonus(-5, 2) == (5, -3)", prelude="GLOBAL_SCORE_BONUS = 10"),
