        E("global_vs_local_join_separator", "전역 구분자와 지역 구분자", "def join_with_global_and_local_separator(parts: list[str], local_separator: str) -> tuple[str, str]:", "parts를 GLOBAL_JOIN_SEPARATOR와 local_separator로 각각 결합해 두 문자열을 반환한다.", "전역 서식 상수와 호출별 지역 서식 값 비교", "join_with_global_and_local_separator(['a', 'b'], '-') == ('a|b', 'a-b')", "join_with_global_and_local_separator([], ',') == ('', '')", "join_with_global_and_local_separator(['x'], '') == ('x', 'x')", prelude="GLOBAL_JOIN_SEPARATOR = '|'"),
